import numpy as np

def eigenvalues_3x3(matrix):
    return np.linalg.eigvals(matrix)

import numpy as np

def rc_step_response(R, C, V_in, t):
    # Returns voltage across capacitor as a function of time array t
    tau = R * C
    return V_in * (1 - np.exp(-t / tau))

def laser_diode_power(eta_d, I, I_th, wavelength):
    import math
    h = 6.62607015e-34
    c = 3e8
    q = 1.602176634e-19
    return eta_d * (I - I_th) * (h * c / (q * wavelength))

def calculate_detectivity(area, bandwidth, nep):
    import math
    return math.sqrt(area * bandwidth) / nep

def calculate_nep(noise_current, responsivity):
    # noise_current in amps, responsivity in A/W
    return noise_current / responsivity

def johnson_noise_voltage(resistance, temperature, bandwidth):
    import math
    k = 1.380649e-23
    return math.sqrt(4 * k * temperature * resistance * bandwidth)

def shot_noise_current(current, bandwidth):
    import math
    q = 1.602176634e-19
    return math.sqrt(2 * q * current * bandwidth)

def photon_radiance_v2(radiance, wavelength):
    import math
    h = 6.62607015e-34
    c = 3e8
    return radiance * wavelength / (h * c)

def calculate_responsivity_v2(quantum_efficiency, wavelength):
    import math
    q = 1.602176634e-19
    h = 6.62607015e-34
    c = 3e8
    return quantum_efficiency * q * wavelength / (h * c)

